// Incremental DOM: per-binding compare, write only if changed
const dom = { text: "", writes: 0 };            // fake DOM text node
const lView = [];                                // per-instance array: stores previous binding values
const BIND = 0;                                  // slot index of the binding

// update block of a template function: "Hello {{name}}"
function update(ctx) {
  if (lView[BIND] !== ctx.name) {                // compare new value with stored one
    lView[BIND] = ctx.name;
    dom.text = "Hello " + ctx.name;              // touch the DOM only on change
    dom.writes++;
  }
}

const ctx = { name: "Ann" };
const steps = ["Ann", "Ann", "Bob", "Bob", "Bob", "Cy"];
for (const n of steps) {
  ctx.name = n;
  update(ctx);                                   // one change detection pass
  console.log("name=" + n + " -> dom='" + dom.text + "' writes=" + dom.writes);
}
// Cost: O(bindings) per pass, memory O(bindings); no tree diff.

// Tiny signal graph: push "dirty", pull with version check and equality cutoff
function signal(v) {
  const s = { v, version: 0, consumers: [] };
  s.get = () => { if (active) { s.consumers.push(active); active.deps.push(s); } return s.v; };
  s.set = (nv) => {
    if (nv === s.v) return;                      // equal value: nothing happens
    s.v = nv; s.version++;
    s.consumers.forEach(c => c.markDirty());     // push only the dirty flag
  };
  return s;
}
let active = null;
function computed(fn, name) {
  const c = { v: undefined, version: 0, dirty: true, deps: [], seen: [], consumers: [], recomputes: 0 };
  c.markDirty = () => { if (!c.dirty) { c.dirty = true; c.consumers.forEach(x => x.markDirty()); } };
  c.get = () => {
    if (active) { c.consumers.push(active); active.deps.push(c); }
    if (c.dirty && c.seen.length) {              // pull: first check producers' versions
      c.deps.forEach(d => d.get && d.get());
      if (c.deps.every((d, i) => d.version === c.seen[i])) c.dirty = false;
    }
    if (c.dirty) {                               // recompute lazily
      const prev = active; active = c; c.deps = [];
      const nv = fn(); active = prev; c.recomputes++; c.seen = c.deps.map(d => d.version);
      c.dirty = false;
      if (nv !== c.v) { c.v = nv; c.version++; } // same result: keep version
    }
    return c.v;
  };
  return c;
}
