// Leak: a long-lived target keeps listeners (and their components) alive
const windowTarget = { listeners: new Set() };   // stands in for window
const on = (fn) => { windowTarget.listeners.add(fn); return () => windowTarget.listeners.delete(fn); };

function openComponent(cleanup) {
  const big = new Array(1000).fill("row");       // component state
  const off = on(() => big.length);              // closure retains `big`
  const destroyCbs = [];
  if (cleanup) destroyCbs.push(off);             // like DestroyRef.onDestroy(off)
  return { destroy() { destroyCbs.forEach(f => f()); } };
}

for (const cleanup of [false, true]) {
  windowTarget.listeners.clear();
  const counts = [];
  for (let i = 0; i < 4; i++) {                  // open and close the route 4 times
    openComponent(cleanup).destroy();
    counts.push(windowTarget.listeners.size);
  }
  console.log((cleanup ? "with cleanup:    " : "without cleanup: ") + "listeners after each cycle = " + counts.join(","));
}
// Growth per cycle means a leak; flat counts mean it returns to baseline.

// Dev-mode double pass: second pass detects a binding that changed (NG0100)
const parent = { title: "Home" };
const child = {
  afterViewInit() { parent.title = "Child loaded"; }  // child writes parent state
};

function bindings() { return { title: parent.title }; }

function tick(devMode) {
  const first = bindings();                      // parent checked first
  console.log("pass 1 rendered:", first.title);
  child.afterViewInit();                         // hook runs after parent was checked
  if (devMode) {
    const second = bindings();                   // checkNoChanges pass
    if (second.title !== first.title) {
      throw new Error("NG0100: '" + first.title + "' -> '" + second.title + "'");
    }
  }
}

try { tick(true); } catch (e) { console.log("dev mode:", e.message); }
parent.title = "Home";
tick(false);
console.log("prod mode: screen shows stale 'Home' but model is '" + parent.title + "'");
tick(false);                                     // next cycle finally shows it

// @for track: by id keeps each row's view with its data; by index rebinds rows
const before = [1, 2, 3, 4, 5].map(id => ({ id }));
const after = [{ id: 0 }].concat(before);        // new row inserted at the top
console.log("before ids:", before.map(r => r.id).join(","));
console.log("after  ids:", after.map(r => r.id).join(","));

function diff(oldRows, newRows, key) {
  let created = 0, rebound = 0;
  newRows.forEach((r, i) => {
    const k = key(r, i);
    const old = oldRows.find((o, j) => key(o, j) === k);
    if (!old) created++;                         // no view with this key: create
    else if (old !== r) rebound++;               // view reused but its data changed
  });
  return "created " + created + ", rebound " + rebound;
}
console.log("track r.id   ->", diff(before, after, r => r.id));
console.log("track $index ->", diff(before, after, (r, i) => i));
// With id keys, existing rows are only moved. With index keys, every row
// view is rebound to a different item. Matching here is O(N^2); real code uses a Map, O(N).
